import logging
import re

log = logging.getLogger("thor.stream")

class Object:
    def __init__(self, path):
        self.name = os.path.basename(path)
        self.path = path

        if os.path.isdir(self.path):
            self.type = DIR_MIME_TYPE
            self.size = None
            self.time = None
        else:
            try:
                stat = os.stat(self.path)
                self.size = stat.st_size
                self.time = stat.st_mtime
            except OSError:
                self.size = None
                self.time = None

            mime = mimetypes.MimeTypes()
            guessed = mime.guess_type(urllib.pathname2url(self.path))[0]

            if guessed == 'application/octet-stream':
                # some useful heuristics for files with unknown mime types
                if re.search("jpe?g", self.name, re.IGNORECASE):
                    guessed = "image/jpeg"
                elif re.search("png", self.name, re.IGNORECASE):
                    guessed = "image/png"
                elif re.search("gif", self.name, re.IGNORECASE):
                    guessed = "image/gif"

                elif re.search("mp4", self.name, re.IGNORECASE):
                    guessed = "video/mp4"
                elif re.search("m4a", self.name, re.IGNORECASE):
                    guessed = "audio/m4a"
                elif re.search("mp3", self.name, re.IGNORECASE):
                    guessed = "audio/mp3"

                elif re.search("pdf", self.name, re.IGNORECASE):
                    guessed = "application/pdf"

            log.debug(("Mime type of", path, "is", guessed))
            self.type = guessed

    @staticmethod
    def get_objects(path):
        objects = []

        if path:
            for name in os.listdir(path):
                object_path = os.path.join(path, name)
                objects.append(Object(object_path))

        return objects

from chainer import cuda
from chainer import function
from chainer.utils import type_check


class Copy(function.Function):

    """Copy an input GPUArray onto another device."""

    def __init__(self, out_device):
        self.out_device = out_device

    def check_type_forward(self, in_types):
        type_check.expect(in_types.size() == 1)
        x_type, _ = in_types

        check_types = type_check.Variable(
            cuda.get_device_from_id(self.out_device).inspect_is_shared_memory(
                x_type.data.ptr),
            ': being copied to shared memory')
        type_check.check_equal(
            type_check.make_variable(cuda.IPtr, 0), check_types)

    def check_type_backward(self, in_types, opt_out_types):
        type_check.expect(in_types.size() == 1)
        x_type, = in_types

        if opt_out_types.size() == 1:
            out_type, = opt_out_types
            type_check.expect(out_type.dtype == x_type.dtype)
            type_check.expect(out_type.shape == x_type.shape)

    def forward_cpu(self, x):
        return x[0].copy(),

    def forward_gpu(self, x):
        return cuda.copy(x[0], out_device=self.out_device),

    def backward_cpu(self, x, gy):
        return gy[0].copy(),

    def backward_gpu(self, x, gy):
        return cuda.copy(gy[0], out_device=cuda.get_device(x[0])),


def copy(x, dst):
    """Copies the input variable onto the specified device.

    This function copies the array of input variable onto the device specified
    by ``dst`` if the original array is on GPU, and otherwise just copies the
    array within host memory.

    Args:
        x (~chainer.Variable): Variable to be copied.
        dst: Target device specifier.

    Returns:
        ~chainer.Variable: Output variable.

    """
    return Copy(dst)(x)

